INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('wcw-nitro-usa', 'N64', 'WCW Nitro (USA)', '1999', 'Wrestling', 'AKI Corporation', '4', 'Arcade Wrestling', 'Professional wrestling with a 2D-style spirit in a 3D world.', 'Conquer the Nitro tour and win the championship belt.', 'A stylized wrestling game featuring the stars of the WCW.', 'WCW Nitro (USA) brings the TV show''s energy to life. Featuring FMV sequences and a massive roster, it offers a unique visual style for N64 wrestling fans.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('wcw-nitro-usa-alt-1', 'N64', 'WCW Nitro (USA) (Alt 1)', '1999', 'Wrestling', 'AKI Corporation', '4', 'Arcade Wrestling', 'Professional wrestling with minor roster or texture changes.', 'Rise to the top of the WCW ranks in this alternative build.', 'An alternative version of the WCW Nitro game for N64.', 'WCW Nitro (USA) (Alt 1) provides a variation of the classic title, featuring the same aggressive gameplay and large cast of legendary wrestlers.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('wcw-vs-nwo---world-tour-europe', 'N64', 'WCW vs. nWo - World Tour (Europe)', '1997', 'Wrestling', 'AKI Corporation', '4', 'Arcade Wrestling', 'Professional wrestling with the legendary AKI grappling engine.', 'Win the world tour and master the technical grappling system.', 'The European version of the first AKI-developed WCW game.', 'WCW vs. nWo - World Tour (Europe) revolutionized wrestling games. With its deep "Grapple" system and realistic move sets, it set the standard for the genre on N64.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('wcw-vs-nwo---world-tour-usa', 'N64', 'WCW vs. nWo - World Tour (USA)', '1997', 'Wrestling', 'AKI Corporation', '4', 'Arcade Wrestling', 'Professional wrestling with the legendary AKI grappling engine.', 'Defeat the nWo and claim the championship for the WCW.', 'The North American release of the groundbreaking wrestling title.', 'WCW vs. nWo - World Tour (USA) is a fan favorite. Experience the tight controls and satisfying physics that made the AKI engine a legend among fighting and sports fans.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('wcw-vs-nwo---world-tour-usa-rev-a', 'N64', 'WCW vs. nWo - World Tour (USA) (Rev A)', '1997', 'Wrestling', 'AKI Corporation', '4', 'Arcade Wrestling', 'Professional wrestling with minor bug fixes and logic updates.', 'Master the ring with the most stable version of World Tour.', 'An updated revision of the North American WCW classic.', 'WCW vs. nWo - World Tour (USA) (Rev A) offers refined gameplay and minor asset corrections, providing the most polished version of this wrestling masterpiece.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('wcw-nwo-revenge-europe', 'N64', 'WCW-nWo Revenge (Europe)', '1998', 'Wrestling', 'AKI Corporation', '4', 'Arcade Wrestling', 'Professional wrestling with expanded rosters and arenas.', 'Win the championship and defend it against the nWo faction.', 'The European release of the highly acclaimed wrestling sequel.', 'WCW-nWo Revenge (Europe) improved on every aspect of its predecessor. With better graphics, more moves, and a deeper roster, it’s a top-tier N64 wrestling experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('wcw-nwo-revenge-usa', 'N64', 'WCW-nWo Revenge (USA)', '1998', 'Wrestling', 'AKI Corporation', '4', 'Arcade Wrestling', 'Professional wrestling with expanded rosters and arenas.', 'Master the ring and humiliate your rivals in this AKI classic.', 'The definitive North American release of the best WCW game.', 'WCW-nWo Revenge (USA) is widely considered one of the greatest wrestling games ever. Featuring iconic entrances and perfect gameplay mechanics, it''s a must-play for N64 owners.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('weird-snake-dimension', 'N64', 'Weird Snake Dimension', '2021', 'Platformer', 'ROM Hack Community', '1', 'Experimental Platformer', 'Surreal 3D platforming with snake-themed environments.', 'Navigate a bizarre world made of snakes and coils to find stars.', 'A creative and abstract mod for the Super Mario 64 engine.', 'Weird Snake Dimension is an artistic and strange modification. Explore a world where everything is serpentine, offering a unique visual and navigational challenge on the N64.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('wetrix-europe-enfrdeesitnl', 'N64', 'Wetrix (Europe) (En,Fr,De,Es,It,Nl)', '1998', 'Puzzle', 'Zed Two', '1', 'Environmental Puzzle', '3D landscape-based puzzle game with water management.', 'Build walls to contain water and earn points as you clear tiles.', 'A highly original and addictive puzzle title for Europe.', 'Wetrix (Europe) combines terraforming with puzzle logic. Create lakes, evaporate water with fireballs, and manage a shifting 3D environment in this colorful and unique N64 game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('wetrix-japan', 'N64', 'Wetrix (Japan)', '1998', 'Puzzle', 'Zed Two', '1', 'Environmental Puzzle', '3D landscape-based puzzle game with water management.', 'Master the terraforming mechanics in the Japanese circuit.', 'The Japanese localized version of the innovative 3D puzzler.', 'Wetrix (Japan) brings the same intense water-based puzzle action to Japan. Featuring vibrant graphics and a rewarding scoring system, it’s a deep and challenging experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('wetrix-usa-enfrdeesitnl', 'N64', 'Wetrix (USA) (En,Fr,De,Es,It,Nl)', '1998', 'Puzzle', 'Zed Two', '1', 'Environmental Puzzle', '3D landscape-based puzzle game with water management.', 'Achieve the highest score by building complex dam systems.', 'The North American release of the water-based puzzle hit.', 'Wetrix (USA) is a test of reflexes and planning. Use varied shapes to raise land and trap falling water while avoiding earthquakes and leaks in this 64-bit puzzle masterpiece.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('wetter-slope-soap', 'N64', 'Wetter Slope Soap', '2022', 'Platformer', 'ROM Hack Community', '1', 'Challenge Platformer', '3D platforming with a custom "Soap" and slipperiness theme.', 'Navigate a world that is incredibly slippery and fast-paced.', 'A unique "slippery" mod for the Super Mario 64 engine.', 'Wetter Slope Soap turns the physics on their head. Every surface acts like ice, requiring expert control and momentum management to find the stars in this fun N64 modification.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('wheel-of-fortune-usa', 'N64', 'Wheel of Fortune (USA)', '1998', 'Game Show', 'GameTek', '2', 'Game Show', '2D-style TV game show simulation with spinning mechanics.', 'Solve the word puzzles to win virtual cash and prizes.', 'A faithful digital version of the famous American game show.', 'Wheel of Fortune (USA) features Vanna White and the classic show format. Compete against friends or AI to solve phrases and spin the wheel in this nostalgic N64 title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('whisper-the-wolf-64', 'N64', 'Whisper The Wolf 64', '2023', 'Platformer', 'ROM Hack Community', '1', 'Story Platformer', '3D platforming featuring Whisper the Wolf from the Sonic series.', 'Use Whisper''s specialized sniper and combat gear to clear stages.', 'A character swap mod featuring the popular IDW Sonic character.', 'Whisper The Wolf 64 brings a new level of cool to the N64. Play as Whisper with custom animations and her iconic look in this high-quality character-focused modification.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('whisper-the-wolf-64-no-mask', 'N64', 'Whisper The Wolf 64 (No mask)', '2023', 'Platformer', 'ROM Hack Community', '1', 'Story Platformer', '3D platforming featuring Whisper without her signature mask.', 'Explore the Mushroom Kingdom as the unmasked Whisper the Wolf.', 'A variant character mod featuring the unmasked Whisper.', 'Whisper The Wolf 64 (No mask) offers a different visual take on the character. Enjoy the same fluid platforming and custom assets with a more personal look for the hero.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('wild-choppers-japan', 'N64', 'Wild Choppers (Japan)', '1997', 'Action', 'Nintendo R&D1', '2', 'Arcade Action', 'High-speed helicopter combat and rescue missions.', 'Fly through dangerous territory and eliminate enemy forces.', 'The Japanese version of the game Chopper Attack.', 'Wild Choppers (Japan) features explosive aerial combat. Choose your pilot and helicopter to complete intense missions across varied 3D landscapes in this action-packed N64 title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('wildwaters-usa-proto', 'N64', 'Wildwaters (USA) (Proto)', '1998', 'Racing', 'Nintendo', '2', 'Water Racing', '3D action-platforming featuring water-based vehicles.', 'Navigate through watery environments in this unreleased build.', 'A rare North American prototype of the cancelled Wildwaters game.', 'Wildwaters (USA) (Proto) provides a fascinating look at an unreleased project. Explore water-filled levels and experience the early development of this vehicle-based N64 title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('winback---covert-operations-usa', 'N64', 'WinBack - Covert Operations (USA)', '2000', 'Action', 'Koei', '2', 'Tactical Shooter', 'Third-person tactical shooter with cover mechanics.', 'Infiltrate a terrorist base and stop a satellite weapon.', 'A pioneer of the cover-based shooter genre on N64.', 'WinBack - Covert Operations (USA) features intense tactical combat. Use walls for cover, manage your ammo, and take down a high-tech terrorist group in this influential 64-bit action title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('winback-japan', 'N64', 'WinBack (Japan)', '1999', 'Action', 'Koei', '2', 'Tactical Shooter', 'Third-person tactical shooter with cover mechanics.', 'Neutralize the Crying Lions terrorist group in Japan.', 'The original Japanese release of the tactical shooter WinBack.', 'WinBack (Japan) introduced players to Jean-Luc Cougar and the innovative "crouch and aim" system. Experience the cinematic story and precise shooting that defined this Koei classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('winback-japan-rev-a', 'N64', 'WinBack (Japan) (Rev A)', '1999', 'Action', 'Koei', '2', 'Tactical Shooter', 'Third-person tactical shooter with refined performance.', 'Master the tactical mission with improved stability.', 'An updated Japanese revision of the tactical hit WinBack.', 'WinBack (Japan) (Rev A) provides a more polished experience of the terrorist infiltration mission, featuring minor bug fixes and optimized game logic for the Nintendo 64.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('wipeout-64-europe', 'N64', 'Wipeout 64 (Europe)', '1999', 'Racing', 'Psygnosis', '2', 'Futuristic Racing', 'High-speed anti-gravity racing with combat elements.', 'Win the F3600 anti-gravity league across futuristic tracks.', 'The European version of the iconic high-speed racing franchise.', 'Wipeout 64 (Europe) features a blistering techno soundtrack and sleek ship designs. Navigate narrow tracks at breakneck speeds while using futuristic weapons to blast your rivals.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('wipeout-64-usa', 'N64', 'Wipeout 64 (USA)', '1999', 'Racing', 'Psygnosis', '2', 'Futuristic Racing', 'High-speed anti-gravity racing with combat elements.', 'Conquer the Challenge mode and master every craft.', 'The North American release of the anti-gravity racing masterpiece.', 'Wipeout 64 (USA) is known for its stylish visuals and intense difficulty. Experience smooth frame rates and satisfying combat-racing mechanics on some of the most creative tracks on the system.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('within-dreams-64', 'N64', 'Within Dreams 64', '2021', 'Platformer', 'ROM Hack Community', '1', 'Story Platformer', '3D platforming in a surreal, dream-like custom environment.', 'Explore a world of imagination to find the hidden Power Stars.', 'A visually artistic and atmospheric mod for Super Mario 64.', 'Within Dreams 64 features soft lighting and creative level design. Wander through a sky-themed world and solve gentle puzzles in this atmospheric and charming N64 fan project.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('wonder-project-j2---koruro-no-mori-no-jozet-japan', 'N64', 'Wonder Project J2 - Koruro no Mori no Jozet (Japan)', '1998', 'Adventure', 'Enix', '1', 'Narrative Adventure', 'Life simulation and adventure with a focus on teaching.', 'Guide the robot girl Josette and teach her how to be human.', 'A beautiful and unique Japan-exclusive adventure game.', 'Wonder Project J2 (Japan) features high-quality 2D art in a 3D world. Interact with Josette, provide guidance, and watch her grow in this heartwarming and technical N64 achievement.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('world-cup-98-europe-enfrdeesitnlsvda', 'N64', 'World Cup 98 (Europe) (En,Fr,De,Es,It,Nl,Sv,Da)', '1998', 'Sports', 'Electronic Arts', '4', 'Soccer Simulation', 'Professional soccer simulation with official 1998 licensing.', 'Lead your nation to victory and win the FIFA World Cup.', 'The European version of the official 1998 World Cup game.', 'World Cup 98 (Europe) captures the excitement of the French tournament. Choose from dozens of international teams and experience realistic soccer with full commentary and crowd chants.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('world-cup-98-usa-enfrdeesitnlsvda', 'N64', 'World Cup 98 (USA) (En,Fr,De,Es,It,Nl,Sv,Da)', '1998', 'Sports', 'Electronic Arts', '4', 'Soccer Simulation', 'Professional soccer simulation with official 1998 licensing.', 'Score the winning goal and lift the gold trophy.', 'The North American release of the official FIFA World Cup sim.', 'World Cup 98 (USA) features authentic stadiums and rosters from the historic tournament. Master the passing and shooting mechanics to guide your country to global glory.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('world-driver-championship-europe-enfrdeesit', 'N64', 'World Driver Championship (Europe) (En,Fr,De,Es,It)', '1999', 'Racing', 'Boss Game Studios', '2', 'Simulation Racing', 'Realistic grand tourer racing with a focus on simulation.', 'Earn your way into the top racing teams and win championships.', 'A technically impressive racing title for the European market.', 'World Driver Championship (Europe) pushes the N64 hardware to its limits. Featuring high-resolution textures and realistic car physics, it is a must-play for fans of simulation racing.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('world-driver-championship-usa', 'N64', 'World Driver Championship (USA)', '1999', 'Racing', 'Boss Game Studios', '2', 'Simulation Racing', 'Realistic grand tourer racing with a focus on simulation.', 'Complete the career mode and unlock high-performance cars.', 'The North American release of the highly detailed racer.', 'World Driver Championship (USA) offers a deep career path and beautiful global tracks. Experience some of the best lighting and vehicle models available on the Nintendo 64.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('worms-armageddon-europe-enfrdeesitnl', 'N64', 'Worms Armageddon (Europe) (En,Fr,De,Es,It,Nl)', '1999', 'Strategy', 'Team17', '4', 'Turn-Based Strategy', 'Turn-based tactical artillery with destructive environments.', 'Use a variety of wacky weapons to eliminate the enemy worms.', 'The European version of the hilarious tactical strategy game.', 'Worms Armageddon (Europe) features an incredible arsenal, from Holy Hand Grenades to Concrete Donkeys. Master the wind and trajectories to be the last worm standing in this N64 classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('worms-armageddon-usa-enfres', 'N64', 'Worms Armageddon (USA) (En,Fr,Es)', '1999', 'Strategy', 'Team17', '4', 'Turn-Based Strategy', 'Turn-based tactical artillery with destructive environments.', 'Defeat the computer or your friends in local multiplayer.', 'The North American release of the addictive Worms strategy title.', 'Worms Armageddon (USA) is the perfect local multiplayer game. With fully destructible terrain and endless customization, it provides hours of strategic and humorous entertainment.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('wwf-attitude-europe', 'N64', 'WWF Attitude (Europe)', '1999', 'Wrestling', 'Acclaim Studios Austin', '4', 'Arcade Wrestling', 'Professional wrestling with a deep career mode and CAW.', 'Win the belt and dominate the "Attitude Era" roster.', 'The European version of the follow-up to WWF War Zone.', 'WWF Attitude (Europe) features a massive roster of superstars. Master the complex button-code finishers and create your own wrestler in the deep "Create-A-Wrestler" mode.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('wwf-attitude-germany', 'N64', 'WWF Attitude (Germany)', '1999', 'Wrestling', 'Acclaim Studios Austin', '4', 'Arcade Wrestling', 'Professional wrestling with localized German text.', 'Rise to the top of the WWF rankings in this German edition.', 'The localized German version of the WWF Attitude wrestling game.', 'WWF Attitude (Germany) brings the chaotic energy of the late 90s wrestling scene to German fans. Experience the full career mode and brutal match types on the N64.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('wwf-attitude-usa', 'N64', 'WWF Attitude (USA)', '1999', 'Wrestling', 'Acclaim Studios Austin', '4', 'Arcade Wrestling', 'Professional wrestling with a deep career mode and CAW.', 'Become the WWF champion and win the hardcore title.', 'The North American release of the content-packed wrestling title.', 'WWF Attitude (USA) is known for its wide variety of match types, including Blood and Cage matches. With over 40 wrestlers and full entrances, it captures the spirit of the era.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('wwf-legends---challenge-64', 'N64', 'WWF LEGENDS - Challenge 64', '2021', 'Wrestling', 'ROM Hack Community', '4', 'Arcade Wrestling', 'Professional wrestling in a retro-inspired challenge format.', 'Win the classic WWF tournaments with legendary icons.', 'A creative mod for the N64 focusing on the Golden Era of wrestling.', 'WWF LEGENDS - Challenge 64 brings Hulk Hogan, Macho Man, and more to the N64. Experience custom textures and rosters that celebrate the heritage of professional wrestling.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('wwf-no-mercy-europe', 'N64', 'WWF No Mercy (Europe)', '2000', 'Wrestling', 'AKI Corporation', '4', 'Simulation Wrestling', 'Professional wrestling with the refined AKI grappling engine.', 'Win the championship and navigate the branching story mode.', 'The European release of the critically acclaimed wrestling game.', 'WWF No Mercy (Europe) is the pinnacle of N64 wrestling. Featuring the deepest career mode on the system and perfect grappling mechanics, it remains a competitive favorite to this day.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('wwf-no-mercy-europe-rev-a', 'N64', 'WWF No Mercy (Europe) (Rev A)', '2000', 'Wrestling', 'AKI Corporation', '4', 'Simulation Wrestling', 'Professional wrestling with the crucial "save bug" fix.', 'Experience the full story mode without losing your progress.', 'A rare European revision that fixes the infamous data loss bug.', 'WWF No Mercy (Europe) (Rev A) is the essential version for PAL players. It corrects the game-breaking save error, allowing you to unlock everything and save your career progress safely.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('wwf-no-mercy-usa', 'N64', 'WWF No Mercy (USA)', '2000', 'Wrestling', 'AKI Corporation', '4', 'Simulation Wrestling', 'Professional wrestling with the refined AKI grappling engine.', 'Unlock all characters and win the main event at WrestleMania.', 'The North American release of the wrestling masterpiece.', 'WWF No Mercy (USA) features an incredible roster and deep customization. Its intuitive controls and satisfying weight-based grappling make it one of the best sports games ever made.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('wwf-no-mercy-usa-rev-a', 'N64', 'WWF No Mercy (USA) (Rev A)', '2000', 'Wrestling', 'AKI Corporation', '4', 'Simulation Wrestling', 'Professional wrestling with the crucial "save bug" fix.', 'Complete the 100% career run with total data security.', 'The corrected North American revision of No Mercy.', 'WWF No Mercy (USA) (Rev A) is highly prized by fans as it fixes the original release''s tendency to erase save data. Enjoy the best wrestling game on N64 with complete peace of mind.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('wwf-no-mercy-aew-64', 'N64', 'WWF No Mercy AEW 64', '2022', 'Wrestling', 'ROM Hack Community', '4', 'Modded Wrestling', 'Professional wrestling featuring the modern AEW roster.', 'Battle as modern stars like Kenny Omega using the No Mercy engine.', 'A high-quality total conversion mod bringing AEW to the N64.', 'WWF No Mercy AEW 64 is a dream for modern wrestling fans. Experience the legendary AKI gameplay with updated textures, movesets, and characters from the All Elite Wrestling roster.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('wwf-war-zone-europe', 'N64', 'WWF War Zone (Europe)', '1998', 'Wrestling', 'Iguana Entertainment', '2', 'Arcade Wrestling', 'Professional wrestling with a focus on arena brawling.', 'Defeat your opponents to become the king of the ring.', 'The first 3D WWF title on the N64, released for Europe.', 'WWF War Zone (Europe) features digitized voices and character models. Master the technical move lists to climb the ranks of the WWF in this classic early-3D wrestling title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('wwf-war-zone-usa', 'N64', 'WWF War Zone (USA)', '1998', 'Wrestling', 'Iguana Entertainment', '2', 'Arcade Wrestling', 'Professional wrestling with a focus on arena brawling.', 'Win the championship gold in the official WWF tournament.', 'The North American release of the groundbreaking 3D wrestler.', 'WWF War Zone (USA) set the stage for future hits. With its challenge mode and unique "button combo" system, it provided a new level of intensity for wrestling fans on the N64.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('wwf-wrestlemania-2000-europe', 'N64', 'WWF WrestleMania 2000 (Europe)', '1999', 'Wrestling', 'AKI Corporation', '4', 'Simulation Wrestling', 'Professional wrestling with the AKI engine and deep CAW.', 'Win the road to WrestleMania and earn the championship.', 'The European version of the first AKI-WWF partnership.', 'WWF WrestleMania 2000 (Europe) features the legendary grappling mechanics of WCW Revenge applied to the WWF roster. Experience authentic entrances and a deep career mode.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('wwf-wrestlemania-2000-japan', 'N64', 'WWF WrestleMania 2000 (Japan)', '1999', 'Wrestling', 'AKI Corporation', '4', 'Simulation Wrestling', 'Professional wrestling with the AKI engine and Japanese icons.', 'Conquer the ring with a massive roster of US and Japanese stars.', 'The Japanese release of the hit WrestleMania 2000 game.', 'WWF WrestleMania 2000 (Japan) features slightly different roster additions and the same perfect gameplay. It remains a staple for fans of technical 3D wrestling on the Nintendo 64.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('wwf-wrestlemania-2000-usa', 'N64', 'WWF WrestleMania 2000 (USA)', '1999', 'Wrestling', 'AKI Corporation', '4', 'Simulation Wrestling', 'Professional wrestling with the AKI engine and deep CAW.', 'Navigate the story mode and win every title in the company.', 'The definitive North American release of the wrestling hit.', 'WWF WrestleMania 2000 (USA) introduced the "Road to WrestleMania" mode and a massive creation suite. Its smooth gameplay and authentic presentation made it an instant classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('x-mas-super-mario-64', 'N64', 'X-Mas Super Mario 64', '2020', 'Platformer', 'ROM Hack Community', '1', 'Seasonal Platformer', 'Festive 3D platforming with Christmas-themed levels.', 'Collect the holiday stars and save Christmas in the castle.', 'A winter-themed holiday hack for Super Mario 64.', 'X-Mas Super Mario 64 is a cozy seasonal adventure. Explore snowy versions of classic stages and enjoy festive music and decorations in this charming N64 fan project.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('xena---warrior-princess---the-talisman-of-fate-europe', 'N64', 'Xena - Warrior Princess - The Talisman of Fate (Europe)', '1999', 'Fighting', 'Titus Software', '2', 'Weapon-Based Fighting', '3D arena fighting game based on the hit TV series.', 'Use the Talisman of Fate to defeat your rivals in combat.', 'The European version of the Xena weapon-based fighter.', 'Xena - Warrior Princess (Europe) features Xena, Gabrielle, and other icons from the show. Master their unique fighting styles and special moves in this 4-player arena brawler.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('xena---warrior-princess---the-talisman-of-fate-usa', 'N64', 'Xena - Warrior Princess - The Talisman of Fate (USA)', '1999', 'Fighting', 'Titus Software', '2', 'Weapon-Based Fighting', '3D arena fighting game based on the hit TV series.', 'Win the tournament of fate and protect the ancient artifacts.', 'The North American release of the Xena action-fighter.', 'Xena - Warrior Princess (USA) allows fans to battle as their favorite heroes and villains. With multi-player support and interactive arenas, it’s a fun brawler for fans of the franchise.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('xplorer-64-germany-v1067-unl', 'N64', 'Xplorer 64 (Germany) (v1.067) (Unl)', '1998', 'Puzzle', 'Iceage Digital Studios', '1', 'Unlicensed Puzzle', 'Cheat utility and save management software.', 'Unlock secrets and manage N64 game data with ease.', 'A localized German version of the Xplorer cheat cartridge software.', 'Xplorer 64 (Germany) is an unofficial utility for power users. Access hidden game codes, manage memory cards, and unlock content in your N64 library with this technical tool.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('yakouchuu-ii---satsujin-kouro-japan', 'N64', 'Yakouchuu II - Satsujin Kouro (Japan)', '1996', 'Adventure', 'Athena', '1', 'Detective Adventure', '2D visual novel and mystery adventure set on a ship.', 'Solve a series of murders and survive the night at sea.', 'A Japan-exclusive suspense thriller and sequel.', 'Yakouchuu II (Japan) features atmospheric storytelling and multiple endings. Navigate a dark narrative filled with mystery and danger in this unique text-based N64 title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('yoshi-story-japan', 'N64', 'Yoshi Story (Japan)', '1998', 'Platformer', 'Nintendo EAD', '2', 'Storybook Platformer', '2.5D side-scrolling platformer with a pop-up book aesthetic.', 'Eat enough fruit to complete the level and defeat Baby Bowser.', 'The original Japanese release of the colorful Yoshi adventure.', 'Yoshi Story (Japan) features vibrant graphics and a unique "Heart Fruit" system. Guide the diverse pack of Yoshis through a charming pop-up book world in this relaxing N64 classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('yoshis-racing-story-v04', 'N64', 'Yoshi''s Racing Story V0.4', '2021', 'Racing', 'ROM Hack Community', '2', 'Kart Racing', 'High-speed 3D racing using the Mario 64 engine.', 'Compete in custom races as Yoshi to win the Grand Prix.', 'A technical racing mod featuring Yoshi as the main driver.', 'Yoshi''s Racing Story V0.4 showcases the versatility of the N64. Experience custom-built tracks and unique kart physics in this early but impressive fan-made racing project.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('yoshis-story-europe-enfrde', 'N64', 'Yoshi''s Story (Europe) (En,Fr,De)', '1998', 'Platformer', 'Nintendo EAD', '2', 'Storybook Platformer', '2.5D side-scrolling platformer with multi-language support.', 'Restore the Super Happy Tree by eating fruit and finding secrets.', 'The European version of the artistic Yoshi platformer.', 'Yoshi''s Story (Europe) is a visual treat for all ages. Master the sniff ability to find hidden items and enjoy the multi-language localization in this beautifully crafted N64 title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('yoshis-story-usa-enja', 'N64', 'Yoshi''s Story (USA) (En,Ja)', '1998', 'Platformer', 'Nintendo EAD', '2', 'Storybook Platformer', '2.5D side-scrolling platformer with dual-language support.', 'Save the Yoshi island from Baby Bowser''s gloom spell.', 'The North American release of the iconic Yoshi title.', 'Yoshi''s Story (USA) offers a unique "Score Attack" gameplay style. With its pre-rendered 3D graphics and interactive music, it remains one of the most charming experiences on the Nintendo 64.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('yuke-yuke!!-trouble-makers-japan', 'N64', 'Yuke Yuke!! Trouble Makers (Japan)', '2000', 'Action', 'Enix', '2', 'Physics Action', 'Side-scrolling 2D action-platformer with a focus on grabbing.', 'Shake and throw enemies to progress through the levels.', 'The original Japanese version of the cult classic Mischief Makers.', 'Yuke Yuke!! Trouble Makers (Japan) is a masterpiece by Treasure. Join Marina Liteyear in a fast-paced adventure filled with unique boss fights and innovative "grab-and-shake" mechanics.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('zelda-64---horrors-of-arcadia', 'N64', 'Zelda 64 - Horrors of Arcadia', '2020', 'Adventure', 'ROM Hack Community', '1', 'Horror Adventure', 'Survival-horror action-adventure in a corrupted Zelda world.', 'Survive the nightmare and find the source of the Arcadia curse.', 'A dark and terrifying horror-themed mod for Ocarina of Time.', 'Zelda 64 - Horrors of Arcadia turns Hyrule into a land of fear. Explore haunting custom dungeons and face terrifying new entities in this atmospheric N64 total conversion.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('zelda-ocarina-of-time-indigo-chapter-2', 'N64', 'Zelda Ocarina Of Time Indigo Chapter 2', '2021', 'Adventure', 'ROM Hack Community', '1', 'Story Adventure', 'Action-adventure with a brand new narrative and locations.', 'Continue the epic journey in the expanded Indigo storyline.', 'The second chapter of the highly ambitious "Indigo" Zelda mod.', 'Zelda Ocarina Of Time Indigo Chapter 2 features custom assets, new music, and a compelling story. Explore unseen parts of Hyrule in this professional-grade N64 fan project.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('zelda-ocarina-of-time-indigo-v010', 'N64', 'Zelda Ocarina Of Time Indigo v0.1.0', '2021', 'Adventure', 'ROM Hack Community', '1', 'Story Adventure', 'Action-adventure featuring a complete world overhaul.', 'Discover the secrets of a new Hyrule in this massive mod.', 'The initial release of the expansive Zelda Indigo project.', 'Zelda Ocarina Of Time Indigo v0.1.0 offers a fresh perspective on the 64-bit legend. With entirely new level geometry and custom lore, it’s a must-play for Zelda fans.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('zelda-ocarina-of-time-indigo-v0110', 'N64', 'Zelda Ocarina Of Time Indigo v0.1.10', '2021', 'Adventure', 'ROM Hack Community', '1', 'Story Adventure', 'Action-adventure with refined performance and bug fixes.', 'Navigate the Indigo world with improved stability and logic.', 'An updated and more stable build of the Zelda Indigo mod.', 'Zelda Ocarina Of Time Indigo v0.1.10 provides a smoother experience of the custom campaign, featuring corrected collision and refined event triggers for the Nintendo 64.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('zelda-revival', 'N64', 'Zelda Revival', '2019', 'Adventure', 'ROM Hack Community', '1', 'Classic Adventure', 'Action-adventure with a focus on restoring a broken world.', 'Revisit familiar lands to revive the spirit of Hyrule.', 'A unique mod centered on the restoration of the Zelda world.', 'Zelda Revival offers a creative take on Ocarina of Time. Complete specialized trials and witness the world change as you restore the light in this thoughtful N64 modification.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('zelda:-the-sealed-palace-13', 'N64', 'Zelda: The Sealed Palace 1.3', '2022', 'Adventure', 'ROM Hack Community', '1', 'Story Adventure', 'Action-adventure with entirely new dungeons and world map.', 'Find the keys to the Sealed Palace and prevent the ancient evil.', 'One of the most complete and acclaimed Zelda mods ever made.', 'Zelda: The Sealed Palace 1.3 is a full-length adventure. Featuring clever puzzles, new items, and a massive original world, it stands as a true fan-made sequel to Ocarina of Time.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('zeldas-birthday', 'N64', 'Zelda''s Birthday', '2020', 'Adventure', 'ROM Hack Community', '1', 'Short Adventure', 'Action-adventure set in a festive and celebratory Hyrule.', 'Complete a brand new quest to celebrate Link''s birthday.', 'A high-quality "Birthday" themed total conversion for Zelda.', 'Zelda''s Birthday is a fun and creative overhaul. Explore new dungeons, interact with festive NPCs, and enjoy a completely original story designed to celebrate the N64 classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('zero-the-jackal-64', 'N64', 'Zero The Jackal 64', '2019', 'Action', 'ROM Hack Community', '1', 'Shooter Action', '3D platforming featuring Zero the Jackal from Sonic Forces.', 'Use Zero''s agility and shadow powers to navigate levels.', 'A character swap mod for Mario 64 featuring Zero (Infinite).', 'Zero The Jackal 64 brings a modern Sonic antagonist to the N64. Master Zero''s unique aesthetic and custom animations in this stylish and cool character-focused project.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('zool---majuu-tsukai-densetsu-japan', 'N64', 'Zool - Majuu Tsukai Densetsu (Japan)', '1995', 'Action', 'Gremlin Interactive', '1', 'Arcade Platformer', 'Action-RPG with monster collection and combat elements.', 'Train powerful monsters to protect the world from evil spirits.', 'A Japan-exclusive RPG and spin-off of the Zool franchise.', 'Zool - Majuu Tsukai Densetsu (Japan) features a deep monster-taming system and 3D exploration. Manage your creatures and master the turn-based combat in this unique N64 RPG.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('â€œflatâ€-lethal-lava-land', 'N64', 'â€œFlatâ€ Lethal Lava Land', '2020', 'Platformer', 'ROM Hack Community', '1', 'Experimental Platformer', '3D platforming on a completely level, obstacle-free plane.', 'Explore the geometry of Lethal Lava Land without the verticality.', 'A technical "flat" modification of the iconic lava stage.', '"Flat" Lethal Lava Land offers a unique perspective on SM64''s design. By removing verticality, it allows players to study the stage layout and textures in a simplified 3D environment.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('007---goldeneye-europe', 'N64', '007 - GoldenEye (Europe)', '1997', 'Shooter', 'Rare', '4', 'First-Person Shooter', 'First-person shooter with stealth and objective-based missions.', 'Infiltrate bases and stop the Janus Syndicate as James Bond.', 'The legendary European release of the definitive N64 FPS.', '007 - GoldenEye (Europe) is the gold standard for console shooters. Experience the cinematic campaign and the revolutionary 4-player split-screen multiplayer that changed gaming forever.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('007---goldeneye-japan', 'N64', '007 - GoldenEye (Japan)', '1997', 'Shooter', 'Rare', '4', 'First-Person Shooter', 'First-person shooter with objective-based missions.', 'Complete espionage tasks and defeat Trevelayan in Japan.', 'The localized Japanese version of the Bond masterpiece.', '007 - GoldenEye (Japan) brings the high-stakes world of MI6 to Japanese fans. Master the gadgets and weaponry of the world''s most famous spy in this optimized N64 classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('007---goldeneye-usa', 'N64', '007 - GoldenEye (USA)', '1997', 'Shooter', 'Rare', '4', 'First-Person Shooter', 'First-person shooter with stealth and objective-based missions.', 'Save the world from a satellite weapon in the iconic campaign.', 'The definitive North American release of the Bond classic.', '007 - GoldenEye (USA) remains a masterpiece of game design. From the Dam to the Facility, master the stealth-action gameplay and the legendary multiplayer arenas on your N64.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('007---the-world-is-not-enough-europe-enfrde', 'N64', '007 - The World Is Not Enough (Europe) (En,Fr,De)', '1999', 'Shooter', 'Eurocom', '4', 'First-Person Shooter', 'First-person shooter with cinematic missions and gadgets.', 'Stop a nuclear threat across diverse global locations.', 'The high-fidelity Bond sequel developed by Eurocom for Europe.', '007 - The World Is Not Enough (Europe) features impressive graphics and gadgets. Experience the thrill of the film with localized European languages and intense tactical FPS action.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('007---the-world-is-not-enough-usa', 'N64', '007 - The World Is Not Enough (USA)', '1999', 'Shooter', 'Eurocom', '4', 'First-Person Shooter', 'First-person shooter with cinematic missions and gadgets.', 'Rescue hostages and diffuse bombs in the North American campaign.', 'The polished North American release of the second Bond N64 title.', '007 - The World Is Not Enough (USA) push the N64''s limits with sophisticated AI and detailed environments. It’s a must-play for fans of tactical, mission-based shooters.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('1080-teneighty-snowboarding-europe-enjafrde', 'N64', '1080 TenEighty Snowboarding (Europe) (En,Ja,Fr,De)', '1998', 'Sports', 'Nintendo EAD', '2', 'Snowboarding', 'Snowboarding simulation with a focus on speed and tricks.', 'Win the race and land high-scoring combos on the slopes.', 'The European version of the premier N64 snowboarding title.', '1080 TenEighty Snowboarding (Europe) features incredible physics and a cool aesthetic. Master the "1080" spin and conquer the icy terrain in this Nintendo sports masterpiece.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('1080-teneighty-snowboarding-japan-usa-enja', 'N64', '1080 TenEighty Snowboarding (Japan, USA) (En,Ja)', '1998', 'Sports', 'Nintendo EAD', '2', 'Snowboarding', 'Snowboarding simulation with fluid physics and trick combos.', 'Defeat the competition and unlock secret riders like the Panda.', 'The combined North American and Japanese release of 1080.', '1080 TenEighty Snowboarding (USA) set a new standard for extreme sports. Experience realistic board handling and diverse weather effects in this high-speed N64 winter classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('40-winks-europe-enesit-proto', 'N64', '40 Winks (Europe) (En,Es,It) (Proto)', '1999', 'Platformer', 'Eurocom', '1', '3D Platformer', '3D platforming with a dream-world theme and puzzles.', 'Rescue your brother from a nightmare world as Ruff or Tumble.', 'A rare European prototype of the creative platformer.', '40 Winks (Europe) (Proto) lets you explore vibrant dreamscapes. Use various transformations and collect cogs to defeat the evil Nitekap in this charming 3D adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('64-de-hakken!!-tamagotchi---minna-de-tamagotchi-world-japan', 'N64', '64 de Hakken!! Tamagotchi - Minna de Tamagotchi World (Japan)', '1997', 'Simulation', 'Bandai', '4', 'Virtual Pet', 'Digital board game with Tamagotchi raising elements.', 'Compete with friends in a virtual board game to win.', 'A Japan-exclusive Tamagotchi party game for the N64.', '64 de Hakken!! Tamagotchi brings the virtual pet craze to the big screen. Play with up to four friends in a board game filled with mini-games and Tamagotchi evolution.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('64-hanafuda---tenshi-no-yakusoku-japan', 'N64', '64 Hanafuda - Tenshi no Yakusoku (Japan)', '1997', 'Card', 'Game Studio', '4', 'Traditional Card Game', 'Traditional Japanese card game with an angelic theme.', 'Master the art of Hanafuda and defeat your opponents.', 'A beautifully illustrated Japan-exclusive Hanafuda title.', '64 Hanafuda - Tenshi no Yakusoku offers a peaceful yet strategic card game experience. Enjoy traditional Japanese aesthetics and relaxing music on your console.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('64-oozumou-japan', 'N64', '64 Oozumou (Japan)', '1997', 'Sports', 'Athena', '4', 'Sumo Wrestling', 'Sumo wrestling simulation with realistic physics.', 'Rise through the ranks of professional Sumo in Japan.', 'The first entry in the N64''s Sumo wrestling series.', '64 Oozumou (Japan) features authentic Sumo traditions and gameplay. Master the timing and force needed to push your opponent out of the ring in this unique sports title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('64-oozumou-2-japan', 'N64', '64 Oozumou 2 (Japan)', '1999', 'Sports', 'Athena', '4', 'Sumo Wrestling', 'Sumo wrestling simulation with improved graphics and rosters.', 'Become a Yokozuna in the definitive N64 Sumo sequel.', 'The expanded second installment of the Sumo wrestling sim.', '64 Oozumou 2 (Japan) adds more depth and customization to the Sumo experience. Experience realistic character models and refined controls in this culturally rich sports game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('64-trump-collection---alice-no-wakuwaku-trump-world-japan', 'N64', '64 Trump Collection - Alice no Wakuwaku Trump World (Japan)', '1997', 'Card', 'Game Studio', '4', 'Card Collection', 'Digital card game collection set in a fantasy world.', 'Win various card games to progress through Alice''s world.', 'A charming Japan-exclusive collection of classic card games.', '64 Trump Collection features Alice in Wonderland themes. Play Poker, Speed, and more against quirky characters in this colorful and accessible N64 title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('64modders-bob-omb-battlefield-remake', 'N64', '64Modder''s Bob-Omb Battlefield Remake', '2023', 'Platformer', 'ROM Hack Community', '1', 'Remake Platformer', '3D platforming with updated textures and geometry.', 'Re-explore the first level of SM64 with a modern makeover.', 'A high-quality remake of the iconic Bob-Omb Battlefield.', '64Modder''s Remake breathes new life into a classic. Experience improved lighting and refined assets that showcase what the N64 engine can do with modern modding tools.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('a-simple-christmas-eve', 'N64', 'A Simple Christmas Eve', '2020', 'Adventure', 'Indie Developer', '1', 'Seasonal Adventure', 'Short 3D platforming with a cozy Christmas theme.', 'Help Mario prepare for Christmas in a peaceful custom world.', 'A short and sweet holiday-themed Mario 64 modification.', 'A Simple Christmas Eve is a relaxing fan project. Enjoy the snow-covered scenery and festive atmosphere in this brief but heartwarming N64 platforming treat.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('a-terrible-fate', 'N64', 'A Terrible Fate', '1999', 'Adventure', 'Indie Developer', '1', 'Dark Narrative Adventure', 'Action-adventure with a dark, Zelda-inspired story.', 'Face your destiny in a world teetering on the edge of ruin.', 'A narrative-driven mod using the Ocarina of Time engine.', 'A Terrible Fate offers a haunting and atmospheric journey. Solve puzzles and encounter mysterious characters in this short but impactful Zelda fan story.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('adventure-in-the-snow-globe', 'N64', 'Adventure in the Snow Globe', '2019', 'Adventure', 'Indie Developer', '1', 'Fantasy Exploration', '3D platforming inside a miniature winter world.', 'Navigate the tiny, snow-filled world to find the Power Stars.', 'A creative mod set entirely within a giant snow globe.', 'Adventure in the Snow Globe features charming verticality and winter physics. Explore the cozy cabin and frozen lake in this imaginative and unique N64 project.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('aerofighters-assault-europe-enfrde', 'N64', 'AeroFighters Assault (Europe) (En,Fr,De)', '1998', 'Shooter', 'Video System', '2', 'Arcade Shooter', 'Flight combat simulation with diverse jets and missions.', 'Defeat a global terrorist organization in high-stakes dogfights.', 'The European version of the fast-paced flight action game.', 'AeroFighters Assault (Europe) offers intense aerial combat across global landmarks. Choose your pilot and master the sky in this action-oriented N64 flight sim.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('aerofighters-assault-usa', 'N64', 'AeroFighters Assault (USA)', '1998', 'Shooter', 'Video System', '2', 'Arcade Shooter', 'Flight combat simulation with diverse jets and missions.', 'Protect the world from nuclear threats across 7 levels.', 'The North American release of the AeroFighters flight sim.', 'AeroFighters Assault (USA) features a cinematic story and multiple game modes. Experience the thrill of jet combat with a variety of missiles and maneuvers on the N64.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('aerogauge-europe-enfrde', 'N64', 'AeroGauge (Europe) (En,Fr,De)', '1997', 'Racing', 'Human Entertainment', '2', 'Futuristic Racing', 'Futuristic racing with flight-capable vehicles.', 'Race at supersonic speeds and fly over track obstacles.', 'The European version of the high-speed futuristic racer.', 'AeroGauge (Europe) challenges your reflexes in the air and on the ground. Master the unique "gauge" mechanics to outrun your rivals in this stylish N64 racing title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('aerogauge-japan-rev-a', 'N64', 'AeroGauge (Japan) (Rev A)', '1997', 'Racing', 'Human Entertainment', '2', 'Futuristic Racing', 'Futuristic racing with flight-capable vehicles.', 'Win the grand prix with refined ship handling and speed.', 'An updated Japanese revision of the futuristic racer.', 'AeroGauge (Japan) (Rev A) provides a polished version of the high-speed racing experience. Navigate complex 3D tracks and master the art of flight-racing on your console.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('aerogauge-usa', 'N64', 'AeroGauge (USA)', '1997', 'Racing', 'Human Entertainment', '2', 'Futuristic Racing', 'Futuristic racing with flight-capable vehicles.', 'Reach the finish line first across various aerial tracks.', 'The North American release of the supersonic racer.', 'AeroGauge (USA) is all about speed and verticality. Choose from a variety of futuristic crafts and find the best racing lines through the sky and tunnels of this N64 title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ai-shougi-3-japan', 'N64', 'AI Shougi 3 (Japan)', '1997', 'Board Game', 'ASCII Corporation', '2', 'Shogi Simulation', 'Strategic board game focused on the traditional Shogi.', 'Outsmart the advanced AI to become a Shogi master.', 'The third entry in the popular Japanese AI Shogi series.', 'AI Shougi 3 (Japan) features a powerful computer opponent and clean visuals. Perfect for enthusiasts of the traditional Japanese "Game of Generals" on the N64.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('aidyn-chronicles---the-first-mage-europe', 'N64', 'Aidyn Chronicles - The First Mage (Europe)', '1999', 'RPG', 'H20 Entertainment', '1', 'Western Fantasy RPG', 'Turn-based RPG with deep character customization.', 'Lead Alaron on an epic quest to lift a magical curse.', 'The European version of the ambitious Western-style RPG.', 'Aidyn Chronicles - The First Mage (Europe) offers a massive open world and a complex magic system. Experience a deep, serious narrative and tactical combat on the N64.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('aidyn-chronicles---the-first-mage-usa', 'N64', 'Aidyn Chronicles - The First Mage (USA)', '1999', 'RPG', 'H20 Entertainment', '1', 'Western Fantasy RPG', 'Turn-based RPG with deep character customization.', 'Explore a huge fantasy world and master the arts of magic.', 'The North American release of the first Aidyn Chronicles.', 'Aidyn Chronicles - The First Mage (USA) is a treat for RPG fans. With its unique stat-based progression and expansive lore, it stands as one of the deepest role-playing games on the system.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('aidyn-chronicles---the-first-mage-usa-rev-a', 'N64', 'Aidyn Chronicles - The First Mage (USA) (Rev A)', '1999', 'RPG', 'H20 Entertainment', '1', 'Western Fantasy RPG', 'Turn-based RPG with refined performance and bug fixes.', 'Embark on the definitive version of Alaron''s epic quest.', 'An updated revision of the North American RPG classic.', 'Aidyn Chronicles - The First Mage (USA) (Rev A) provides the most stable experience for this massive adventure, fixing minor glitches and optimizing the N64''s performance.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('air-boarder-64-europe', 'N64', 'Air Boarder 64 (Europe)', '1997', 'Sports', 'Human Entertainment', '2', 'Snowboarding', 'Futuristic boarding with high-speed air-decks.', 'Win the tournament and master the tricks in neon cities.', 'The European version of the futuristic boarding racer.', 'Air Boarder 64 (Europe) features a high-energy aesthetic and fast gameplay. Master the "Air Board" physics and land massive combos to dominate the professional circuit.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('air-boarder-64-japan', 'N64', 'Air Boarder 64 (Japan)', '1997', 'Sports', 'Human Entertainment', '2', 'Snowboarding', 'Futuristic boarding with high-speed air-decks.', 'Beat the rival boarders in the Japanese boarding league.', 'The original Japanese release of the futuristic racer.', 'Air Boarder 64 (Japan) offers a unique take on the racing genre. Use hover-technology to navigate creative tracks and prove your skill as the ultimate air boarder.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('akumajou-dracula-mokushiroku---real-action-adventure-japan', 'N64', 'Akumajou Dracula Mokushiroku - Real Action Adventure (Japan)', '1999', 'Action', 'Konami', '1', 'Gothic Action Adventure', 'Gothic action-adventure with 3D platforming and combat.', 'Guide Carrie or Reinhardt to defeat Dracula in his castle.', 'The Japanese version of the first 3D Castlevania game.', 'Akumajou Dracula Mokushiroku (Japan) brings the legendary series to 3D. Explore the dark halls of Castlevania, solve puzzles, and battle the undead in this atmospheric N64 title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('akumajou-dracula-mokushiroku-gaiden---legend-of-cornell-japan', 'N64', 'Akumajou Dracula Mokushiroku Gaiden - Legend of Cornell (Japan)', '1999', 'Action', 'Konami', '1', 'Dark Action Adventure', 'Gothic action-adventure featuring new characters and paths.', 'Master Cornell''s werewolf powers to save his sister.', 'The Japanese release of the expanded Castlevania: Legacy of Darkness.', 'Akumajou Dracula Mokushiroku Gaiden features improved graphics and new gameplay modes. Play as the man-beast Cornell in this definitive 3D Castlevania experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('all-star-tennis-99-europe-enfrdeesit', 'N64', 'All Star Tennis ''99 (Europe) (En,Fr,De,Es,It)', '1999', 'Sports', 'Ubi Soft', '2', 'Tennis Simulation', 'Realistic tennis simulation with professional rosters and tournaments.', 'Win the Grand Slam and master the various court surfaces.', 'The European multi-language release of the technical tennis sim.', 'All Star Tennis ''99 (Europe) features a deep career mode and realistic ball physics. Compete against top pros in iconic stadiums with fluid N64 controls and various match types.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('all-star-tennis-99-usa', 'N64', 'All Star Tennis 99 (USA)', '1999', 'Sports', 'Ubi Soft', '2', 'Tennis Simulation', 'Realistic tennis simulation with professional rosters and tournaments.', 'Achieve the world number one ranking in the pro circuit.', 'The North American release of the acclaimed tennis simulation.', 'All Star Tennis 99 (USA) offers precise shot control and diverse gameplay modes. Whether playing singles or doubles, experience authentic tennis action on your Nintendo 64.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('all-star-baseball-2000-europe', 'N64', 'All-Star Baseball 2000 (Europe)', '2000', 'Sports', 'Acclaim', '4', 'Baseball Simulation', 'Professional baseball simulation with MLB licensing.', 'Lead your team to victory in the 2000 World Series.', 'The European version of the highly detailed baseball sim.', 'All-Star Baseball 2000 (Europe) features Derek Jeter on the cover and offers a deep management system. Enjoy realistic player animations and authentic MLB stadiums on the N64.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('all-star-baseball-2000-usa', 'N64', 'All-Star Baseball 2000 (USA)', '2000', 'Sports', 'Acclaim', '4', 'Baseball Simulation', 'Professional baseball simulation with MLB licensing.', 'Master the batting and pitching mechanics to win the title.', 'The definitive North American release of the 2000 season sim.', 'All-Star Baseball 2000 (USA) set a new standard for sports visuals. With high-resolution graphics and play-by-play commentary, it’s a premier baseball experience for N64 fans.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('all-star-baseball-2001-usa', 'N64', 'All-Star Baseball 2001 (USA)', '2001', 'Sports', 'Acclaim', '4', 'Baseball Simulation', 'Professional baseball simulation with updated 2001 rosters.', 'Outsmart the AI and win the championship with modern stats.', 'The final N64 entry in the acclaimed All-Star Baseball series.', 'All-Star Baseball 2001 (USA) brings refined gameplay and the most up-to-date rosters of the era. Experience the pinnacle of 64-bit baseball simulation with improved physics.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('all-star-baseball-99-europe', 'N64', 'All-Star Baseball 99 (Europe)', '1999', 'Sports', 'Acclaim', '4', 'Baseball Simulation', 'Professional baseball simulation with a focus on realism.', 'Win the 99 season and master the technical controls.', 'The European version of the first 3D All-Star Baseball.', 'All-Star Baseball 99 (Europe) introduced the innovative batting cursor system. Experience the tension of the diamond with licensed teams and realistic 3D environments.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('all-star-baseball-99-usa', 'N64', 'All-Star Baseball 99 (USA)', '1999', 'Sports', 'Acclaim', '4', 'Baseball Simulation', 'Professional baseball simulation with a focus on realism.', 'Dominate the league and earn the MVP award.', 'The North American release of the groundbreaking baseball hit.', 'All-Star Baseball 99 (USA) features detailed player models and a deep season mode. Its intuitive controls and authentic presentation made it a sports staple on the N64.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('an-adventure-and-a-half', 'N64', 'An Adventure and a Half', '2021', 'Platformer', 'Indie Developer', '1', 'Comedy Platformer', '3D platforming with a focus on exploration and light story.', 'Navigate custom worlds to complete a whimsical quest.', 'A creative and lighthearted ROM hack for Super Mario 64.', 'An Adventure and a Half offers unique level design and a fresh narrative. Explore imaginative custom environments and solve puzzles in this charming N64 fan project.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('animal-crossing-doubutsu-no-mori-english', 'N64', 'Animal crossing (Doubutsu no Mori English)', '2001', 'Simulation', 'Nintendo EAD', '4', 'Life Simulation', 'Social simulation and life management in a real-time world.', 'Pay off your home loan and live your best life in a village.', 'The community-translated English version of the original N64 title.', 'Animal Crossing (English) allows Western fans to experience the origins of the series. Live among quirky animals, fish, and decorate your home in this localized N64 masterpiece.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('animal-crossing-doubutsu-no-mori', 'N64', 'Animal crossing (Doubutsu no Mori)', '2001', 'Simulation', 'Nintendo EAD', '4', 'Life Simulation', 'Social simulation and life management in a real-time world.', 'Collect furniture, fish, and bugs while befriending neighbors.', 'The original Japanese release (Doubutsu no Mori).', 'Animal Crossing (Japan) is a unique title that follows a real-time clock. Experience a peaceful life in a persistent world that continues even when you''re not playing.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('another-mario-adventure', 'N64', 'Another Mario Adventure', '2018', 'Platformer', 'ROM Hack Community', '1', 'Fan Platformer', '3D platforming with creative custom worlds and mechanics.', 'Recover the Power Stars in a brand new N64 world.', 'A high-quality adventure hack using the Super Mario 64 engine.', 'Another Mario Adventure provides diverse levels and original challenges. Explore expertly crafted stages that offer a perfect balance of classic gameplay and new ideas for the N64.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('arcade-fighter-64', 'N64', 'Arcade Fighter 64', '1998', 'Fighting', 'Independent', '2', 'Arcade Fighting', 'Arena-based 2D/3D fighting with a focus on arcade mechanics.', 'Defeat a roster of custom fighters in intense combat.', 'A unique technical showcase for fighting gameplay on N64.', 'Arcade Fighter 64 brings high-energy brawling to the console. Master unique character movesets and enjoy fast-paced combat in this creative community-driven fighting project.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('armorines---project-swarm-europe', 'N64', 'Armorines - Project S.W.A.R.M. (Europe)', '1999', 'Shooter', 'Saffire', '4', 'First-Person Shooter', 'First-person shooter with a focus on futuristic insect combat.', 'Save humanity from a global swarm of alien insects.', 'The European release of the sci-fi shooter based on the comic.', 'Armorines - Project S.W.A.R.M. (Europe) features a dark, industrial aesthetic and intense bug-blasting action. Use a variety of high-tech suits and weapons to survive the invasion.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('armorines---project-swarm-germany', 'N64', 'Armorines - Project S.W.A.R.M. (Germany)', '1999', 'Shooter', 'Saffire', '4', 'First-Person Shooter', 'First-person shooter with localized German text and assets.', 'Neutralize the S.W.A.R.M. threat in this specialized version.', 'The German version of the futuristic insect-themed shooter.', 'Armorines - Project S.W.A.R.M. (Germany) offers the same intense sci-fi combat with regional localization. Protect Earth from the alien horde in this atmospheric N64 FPS.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('armorines---project-swarm-usa', 'N64', 'Armorines - Project S.W.A.R.M. (USA)', '1999', 'Shooter', 'Saffire', '4', 'First-Person Shooter', 'First-person shooter with co-op support and futuristic guns.', 'Destroy the alien hives and protect the planet.', 'The North American release of the Armorines action title.', 'Armorines - Project S.W.A.R.M. (USA) is an adrenaline-fueled shooter. Featuring massive bosses and diverse weapons, it’s a high-stakes battle for survival on the Nintendo 64.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('army-men---air-combat-usa', 'N64', 'Army Men - Air Combat (USA)', '2000', 'Action', 'Pandemic Studios', '2', 'Military Shooter', 'Aerial helicopter combat with plastic toy soldiers.', 'Complete missions across household environments to win the war.', 'A fun, aerial-focused spin-off of the Army Men series.', 'Army Men - Air Combat (USA) takes the battle to the sky. Pilot various toy helicopters and protect your green troops from the tan army in this creative N64 flight game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('army-men---sarges-heroes-europe-enfrde', 'N64', 'Army Men - Sarge''s Heroes (Europe) (En,Fr,De)', '1999', 'Action', 'Pandemic Studios', '2', 'Third-Person Action', 'Third-person shooter featuring plastic toy soldier combat.', 'Lead Sarge behind enemy lines to defeat the Tan army.', 'The European release of the iconic toy soldier adventure.', 'Army Men - Sarge''s Heroes (Europe) brings childhood imagination to life. Battle through oversized household rooms and tactical war zones in this nostalgic N64 shooter.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('army-men---sarges-heroes-usa', 'N64', 'Army Men - Sarge''s Heroes (USA)', '1999', 'Action', 'Pandemic Studios', '2', 'Third-Person Action', 'Third-person shooter featuring plastic toy soldier combat.', 'Sabotage the Tan army''s plans across various 3D missions.', 'The North American release of the fan-favorite toy shooter.', 'Army Men - Sarge''s Heroes (USA) features a large cast of characters and creative weaponry. Experience the "real world" from a toy''s perspective in this classic action title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('army-men---sarges-heroes-2-usa', 'N64', 'Army Men - Sarge''s Heroes 2 (USA)', '2000', 'Action', 'Pandemic Studios', '2', 'Third-Person Action', 'Third-person shooter with expanded missions and mechanics.', 'Defeat the Tan army once and for all in this heroic sequel.', 'The refined follow-up to the original Sarge''s Heroes.', 'Army Men - Sarge''s Heroes 2 (USA) offers improved graphics and more diverse mission objectives. Fight through kitchen, bedroom, and backyard stages to save the toy world.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('asteroids-hyper-64-usa', 'N64', 'Asteroids Hyper 64 (USA)', '2000', 'Action', 'Atari Games', '2', 'Arcade Space Shooter', 'Arcade space shooter with a 3D visual overhaul.', 'Destroy asteroids and UFOs to survive as long as possible.', 'A modern 3D reimagining of the classic Asteroids arcade game.', 'Asteroids Hyper 64 (USA) brings the retro hit to the N64. Featuring 4-player co-op, power-ups, and massive boss battles, it’s a high-energy update of a timeless gaming legend.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('automobili-lamborghini-europe', 'N64', 'Automobili Lamborghini (Europe)', '1997', 'Racing', 'Titus Software', '2', 'Realistic Racing', 'High-speed arcade racing with licensed Lamborghini cars.', 'Win championships to unlock faster cars and more tracks.', 'The European version of the licensed supercar racer.', 'Automobili Lamborghini (Europe) features sleek 3D models and intense speed. Master the tight handling of iconic Italian supercars across global tracks in this N64 classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('automobili-lamborghini-usa', 'N64', 'Automobili Lamborghini (USA)', '1997', 'Racing', 'Titus Software', '2', 'Realistic Racing', 'High-speed arcade racing with licensed Lamborghini cars.', 'Defeat your rivals in a pursuit for the ultimate finish line.', 'The North American release of the stylish supercar racer.', 'Automobili Lamborghini (USA) is an arcade fan''s dream. With its sense of speed and accessible controls, it remains a satisfying racing experience for N64 enthusiasts.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('b3313-super-mario-64-internal-plexus', 'N64', 'B3313 (Super Mario 64 Internal Plexus)', '2021', 'Adventure', 'ROM Hack Community', '1', 'Exploration Horror', 'Surreal exploration-horror 3D platforming.', 'Wander through an infinite, distorted castle of dreams.', 'A legendary "Liminal Space" and horror mod for SM64.', 'B3313 (Internal Plexus) is a surreal masterpiece. Explore thousands of distorted and nostalgic custom rooms in a vast, non-linear map that captures the "personalized copy" myth of the N64 era.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('b3313-v07', 'N64', 'B3313 (v0.7)', '2022', 'Adventure', 'ROM Hack Community', '1', 'Exploration Horror', 'Surreal exploration-horror 3D platforming.', 'Uncover the mysteries of a decaying and endless castle.', 'Version 0.7 of the massive B3313 surrealism mod.', 'B3313 (v0.7) provides a deep dive into the "Every Copy is Personalized" lore. Experience glitchy environments, haunting music, and a world that feels both familiar and terrifying.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('b3313-unabandoned-unofficial-10', 'N64', 'B3313 Unabandoned (unofficial 1.0)', '2023', 'Adventure', 'ROM Hack Community', '1', 'Experimental Horror', 'Surreal exploration-horror 3D platforming with fixes.', 'Navigate the most stable version of the infinite castle.', 'A fan-led project to polish and complete the B3313 experience.', 'B3313 Unabandoned is the definitive way to experience the surrealist mod. With improved navigation and fixed content, it’s the ultimate journey through Mario''s 64-bit nightmare.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('baku-bomber-man-japan', 'N64', 'Baku Bomber Man (Japan)', '1997', 'Action', 'Hudson Soft', '4', 'Arcade Bomber Action', 'Action-puzzle platforming with massive explosions.', 'Bomb your way through levels to defeat the evil Sirius.', 'The Japanese release of the first Bomberman 64.', 'Baku Bomber Man (Japan) features the revolutionary 3D circular bomb mechanics. Solve puzzles and defeat giant bosses in this vibrant and strategic N64 adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('baku-bomber-man-2-japan', 'N64', 'Baku Bomber Man 2 (Japan)', '1998', 'Action', 'Hudson Soft', '4', 'Arcade Bomber Action', 'Action-puzzle platforming with refined mechanics and co-op.', 'Stop the BHB army and save the galaxy from destruction.', 'The Japanese version of the acclaimed Bomberman 64: The Second Attack.', 'Baku Bomber Man 2 (Japan) is highly prized by collectors. With the addition of Pommy and elemental bomb types, it offers a deep and rewarding RPG-lite experience on the N64.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bakuretsu-muteki-bangaioh-japan', 'N64', 'Bakuretsu Muteki Bangaioh (Japan)', '1999', 'Action', 'Treasure', '2', 'Run and Gun Shooter', '2D side-scrolling mecha action with high-speed combat.', 'Destroy everything on screen to achieve the high score.', 'A frantic and highly acclaimed cult classic by Treasure.', 'Bangaioh (Japan) is an N64 masterpiece of 2D chaos. Manage your missile gauges and unleash screen-clearing attacks in this rare and technically impressive shooter.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bakushou-jinsei-64---mezase!-resort-ou-japan', 'N64', 'Bakushou Jinsei 64 - Mezase! Resort Ou (Japan)', '1998', 'Simulation', 'Hudson Soft', '4', 'Life Simulation', 'Digital board game with a focus on life simulation and humor.', 'Build a successful life to become the ultimate Resort King.', 'A funny and colorful Japan-exclusive board game.', 'Bakushou Jinsei 64 provides a lighthearted take on the "Game of Life" genre. Compete with friends through various life stages filled with mini-games and N64 charm.');
