INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('banjo-kazooie-worlds-collide', 'N64', 'Banjo-Kazooie Worlds Collide', '2023', 'Platformer', 'ROM Hack Community', '1', 'Crossover Platformer', '3D platforming crossover with multiple Rareware properties.', 'Navigate levels where different game worlds have merged.', 'A massive crossover mod featuring assets from various Rare games.', 'Banjo-Kazooie Worlds Collide is a tribute to Rare''s N64 history. Experience a mashup of levels and characters in this ambitious and technically impressive project.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('banjo-kazooie:-cut-throat-coast', 'N64', 'Banjo-Kazooie: Cut-Throat Coast', '2021', 'Platformer', 'ROM Hack Community', '1', 'Adventure Platformer', '3D platforming with a pirate and tropical theme.', 'Survive the dangerous coast and recover the stolen Jiggies.', 'A high-stakes pirate adventure hack for the N64.', 'Banjo-Kazooie: Cut-Throat Coast features tropical islands, naval ships, and custom NPCs. Experience a swashbuckling journey with the iconic duo in this creative mod.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('banjo-speedie', 'N64', 'Banjo-Speedie', '1999', 'Racing', 'Fan Developer', '1', 'Arcade Racing', '3D platforming focused on high-speed movement.', 'Complete modified levels as fast as possible to set records.', 'A "speedrun-focused" modification of the original game.', 'Banjo-Speedie tweaks the duo''s physics and world layout for maximum velocity. It’s the ultimate challenge for N64 players who feel the need for speed.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('banjo-tooie-australia', 'N64', 'Banjo-Tooie (Australia)', '2000', 'Platformer', 'Rare', '1', '3D Platformer', '3D platforming with massive worlds and "split-up" mechanics.', 'Stop Gruntilda''s giant drill and restore the Isle o'' Hags.', 'The Australian PAL release of the epic N64 sequel.', 'Banjo-Tooie (Australia) offers the complete, massive adventure for the Oceania region. Master the complex moves and vast worlds that pushed the N64 to its limits.');
