INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('banjo-tooie-usa', 'N64', 'Banjo-Tooie (USA)', '2000', 'Platformer', 'Rare', '1', '3D Platformer', '3D platforming with massive worlds and "split-up" mechanics.', 'Complete the ultimate collect-a-thon in North America.', 'The definitive North American release of the Banjo sequel.', 'Banjo-Tooie (USA) is a technical marvel. With its interconnected worlds, first-person segments, and boss battles, it is a masterclass in N64 platforming design.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bass-rush---ecogear-powerworm-championship-japan', 'N64', 'Bass Rush - ECOGEAR PowerWorm Championship (Japan)', '1999', 'Sports', 'ECOGEAR', '1', 'Fishing Simulation', 'Professional bass fishing simulation with licensed gear.', 'Win the championship and catch the biggest record-breaking bass.', 'A Japan-exclusive fishing title featuring real-world tackle.', 'Bass Rush (Japan) offers realistic fishing mechanics and underwater views. Use specialized "PowerWorm" lures to dominate the pro circuit on your N64.');
