INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('body-harvest-usa', 'N64', 'Body Harvest (USA)', '1998', 'Action DMA Design', '1', 'Open-World Action', NULL, 'Open-world action-adventure with vehicles and exploration.', 'Eliminate the alien hives in Greece, Java, and America.', 'The North American release of the landmark adventure.', 'Body Harvest (USA) is known for its incredible scale and freedom. Pilot planes, tanks, and cars to combat giant insects in this 64-bit cult classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bokujou-monogatari-2-japan', 'N64', 'Bokujou Monogatari 2 (Japan)', '1999', 'Simulation', 'Victor Interactive', '1', 'Farming Simulation', 'Farming simulation and life management in 3D.', 'Inherit your grandfather''s farm and build a successful life.', 'The original Japanese release of Harvest Moon 64.', 'Bokujou Monogatari 2 (Japan) is a beloved social sim. Grow crops, raise animals, and find love in the countryside in this deeply addictive N64 classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bokujou-monogatari-2-japan-rev-a', 'N64', 'Bokujou Monogatari 2 (Japan) (Rev A)', '1999', 'Simulation', 'Victor Interactive', '1', 'Farming Simulation', 'Farming simulation with minor bug fixes and event polish.', 'Build the ultimate farm with improved game stability.', 'An updated Japanese revision of the farming simulator.', 'Bokujou Monogatari 2 (Japan) (Rev A) provides a more polished experience of the rural life, ensuring smooth performance for your three-year farming journey.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bokujou-monogatari-2-japan-rev-b', 'N64', 'Bokujou Monogatari 2 (Japan) (Rev B)', '1999', 'Simulation', 'Victor Interactive', '1', 'Farming Simulation', 'Farming simulation with final technical refinements.', 'Experience the countryside with the most stable Japanese build.', 'The final technical revision for the Japanese Harvest Moon.', 'Bokujou Monogatari 2 (Japan) (Rev B) is the definitive version of the game, fixing rare logic errors and optimizing the experience for longtime players.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bomber-man-64-japan', 'N64', 'Bomber Man 64 (Japan)', '1997', 'Action', 'Hudson Soft', '4', 'Action Maze', 'Action-puzzle platforming with 3D movement.', 'Defeat the evil Sirius and save Planet Bomber.', 'The Japanese version of the first 3D Bomberman 64.', 'Bomber Man 64 (Japan) features the iconic "bomb-pumping" mechanic. Navigate 3D worlds and solve physics-based puzzles in this vibrant action title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bomber-man-hero---mirian-oujo-o-sukue!-japan', 'N64', 'Bomber Man Hero - Mirian Oujo o Sukue! (Japan)', '1998', 'Action', 'Hudson Soft', '1', 'Action Adventure', 'High-speed action-platforming with a focus on movement.', 'Rescue Princess Millian and defeat the Garaden Empire.', 'The Japanese release of the linear platformer Bomberman Hero.', 'Bomber Man Hero (Japan) trades puzzles for pure platforming speed. Use jetpacks, submarines, and snowboards to save the day in this energetic N64 game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bomberman-64---the-second-attack!-usa', 'N64', 'Bomberman 64 - The Second Attack! (USA)', '2000', 'Action', 'Hudson Soft', '4', 'Action Maze', 'Action-puzzle with RPG elements and elemental bombs.', 'Stop the BHB army and uncover the truth of Rukifellth.', 'The North American release of the acclaimed Bomberman sequel.', 'Bomberman 64 - The Second Attack! (USA) is a rare and highly prized title. With co-op gameplay and deep mechanics, it’s a premier experience for the console.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bomberman-64-europe', 'N64', 'Bomberman 64 (Europe)', '1997', 'Action', 'Hudson Soft', '4', 'Action Maze', 'Action-puzzle platforming with circular bomb explosions.', 'Master the 3D environments and defeat giant boss threats.', 'The European release of the groundbreaking 3D Bomberman.', 'Bomberman 64 (Europe) features a unique single-player mode and the classic 4-player multiplayer battle mode that fans know and love.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bomberman-64-usa', 'N64', 'Bomberman 64 (USA)', '1997', 'Action', 'Hudson Soft', '4', 'Action Maze', 'Action-puzzle platforming with circular bomb explosions.', 'Find all the Gold Cards and unlock secret levels.', 'The North American release of the 3D Bomberman hit.', 'Bomberman 64 (USA) redefined the series. Use bombs as platforms and master the timing of explosions to conquer the diverse worlds on your N64.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bomberman-hero-europe', 'N64', 'Bomberman Hero (Europe)', '1998', 'Action', 'Hudson Soft', '1', 'Action Adventure', 'Linear action-platformer with a focus on gadgets.', 'Fly, swim, and jet through levels to defeat the invaders.', 'The European version of the platform-heavy Bomberman title.', 'Bomberman Hero (Europe) features a unique electronic soundtrack and fast-paced gameplay. Focus on jumping and combat in this distinct departure from the puzzle roots.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bomberman-hero-usa', 'N64', 'Bomberman Hero (USA)', '1998', 'Action', 'Hudson Soft', '1', 'Action Adventure', 'Linear action-platformer with a focus on gadgets.', 'Earn the highest rank in every level and save the galaxy.', 'The North American release of the fast-paced action game.', 'Bomberman Hero (USA) is an adrenaline-filled journey. With its unique power-ups and varied boss fights, it’s a high-energy platformer that showcases a different side of Bomber.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bottom-of-the-9th-usa', 'N64', 'Bottom of the 9th (USA)', '1999', 'Sports', 'Konami', '2', 'Baseball Simulation', 'Professional baseball with an arcade feel and real rosters.', 'Hit home runs and lead your team to the championships.', 'A polished baseball title featuring MLB stars.', 'Bottom of the 9th (USA) offers fast-paced baseball action. With intuitive controls and multiple modes, it’s an accessible and fun sports game for the Nintendo 64.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bounce-high-skyland', 'N64', 'Bounce-High Skyland', '2021', 'Platformer', 'Fan Developer', '1', 'Exploration Platformer', 'High-altitude 3D platforming above the clouds.', 'Collect stars while navigating floating islands and airships.', 'A creative sky-themed mod for the Super Mario 64 engine.', 'Bounce-High Skyland features vertical level design and breezy aesthetics. Master the art of the triple jump in this imaginative world set high in the N64 sky.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bowser-jr-64', 'N64', 'Bowser Jr 64', '2021', 'Platformer', 'ROM Hack Community', '1', 'Character Platformer', '3D platforming featuring Bowser''s mischievous son.', 'Explore the Mushroom Kingdom as the prince of the Koopas.', 'A character-swap mod featuring a custom Bowser Jr. model.', 'Bowser Jr 64 allows you to play as the iconic villain-in-training. With custom animations and his signature look, experience Mario 64 from a different perspective.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bowser-simulator-demo', 'N64', 'Bowser Simulator Demo', '2020', 'Simulation', 'ROM Hack Community', '1', 'Character Simulation', 'Character simulation with heavy physics and power moves.', 'Test the movement and destructive capabilities of Bowser.', 'A technical demo featuring Bowser as the lead character.', 'Bowser Simulator Demo allows players to step into the shell of the Koopa King. Experience custom physics and specialized animations in this early-access N64 character showcase.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bowsers-castle-break-in', 'N64', 'Bowser''s Castle Break-In', '2021', 'Platformer', 'ROM Hack Community', '1', 'Challenge Platformer', 'Stealth and action-platforming in a high-security fortress.', 'Infiltrate Bowser''s Castle and recover the stolen treasures.', 'A mission-based infiltration mod for the SM64 engine.', 'Bowser''s Castle Break-In features tight level design and environmental puzzles. Navigate through traps and security to reclaim what''s yours in this intense fan-made adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bowsers-castle-slide', 'N64', 'Bowser''s Castle Slide', '2020', 'Platformer', 'ROM Hack Community', '1', 'Slide Challenge', 'High-speed sliding and precision movement challenge.', 'Reach the bottom of the castle slide without falling.', 'A dedicated racing/sliding level mod set in Bowser''s fortress.', 'Bowser''s Castle Slide is a test of reflexes and control. Master the sharp turns and steep drops in this focused, arcade-style N64 platforming challenge.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bowsers-dank-rave', 'N64', 'Bowser''s Dank Rave', '2016', 'Meme', 'ROM Hack Community', '1', 'Meme Platformer', 'Surreal comedy-platforming with flashing lights and loud music.', 'Survive the "dank" party and collect the stars.', 'A legendary "meme-mod" known for its loud and colorful chaos.', 'Bowser''s Dank Rave turns Mario 64 into a surreal disco nightmare. Experience internet humor and high-energy music in this cult classic N64 modification.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bowsers-dank-rave-chaos-edition', 'N64', 'Bowser''s Dank Rave (Chaos Edition)', '2016', 'Meme', 'ROM Hack Community', '1', 'Meme Platformer', 'High-speed chaotic platforming with randomized effects.', 'Navigate the rave with extreme speed and visual glitches.', 'The "Chaos Edition" of the first Dank Rave mod.', 'Bowser''s Dank Rave (Chaos Edition) amps up the intensity with unpredictable physics and visual flair. It’s a frantic, sensory-overload experience for N64 mod enthusiasts.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bowsers-dank-rave-2---return-of-the-illuminati-dubstep-party', 'N64', 'Bowser''s Dank Rave 2 - Return of the Illuminati Dubstep Party', '2017', 'Meme', 'ROM Hack Community', '1', 'Meme Platformer', 'Surreal comedy-platforming with a dubstep theme.', 'Save the party from the Illuminati threat.', 'The second entry in the humorous Dank Rave series.', 'Bowser''s Dank Rave 2 features more complex levels and even louder music. Dive into the world of 2010s internet culture with this hilarious and bizarre N64 fan project.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bowsers-dank-rave-2-chaos-edition', 'N64', 'Bowser''s Dank Rave 2 (Chaos Edition)', '2017', 'Meme', 'ROM Hack Community', '1', 'Meme Platformer', 'High-speed chaotic platforming with dubstep and glitches.', 'Survive the ultimate Illuminati party in chaos mode.', 'The randomized and faster version of Dank Rave 2.', 'Bowser''s Dank Rave 2 (Chaos Edition) is a test of patience and skill. With everything moving at 2x speed, only the most dedicated players will find every star in the rave.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bowsers-dank-rave-2017-edition---extra-long-name-that-i-dont-feel-li', 'N64', 'Bowser''s Dank Rave 2017 Edition - Extra Long Name That I Don''t Feel Li', '2017', 'Meme', 'ROM Hack Community', '1', 'Meme Platformer', 'Expanded comedy-platforming with extra-long challenges.', 'Complete the ultimate party marathon.', 'A 2017 update to the Dank Rave series with extra content.', 'Bowser''s Dank Rave 2017 Edition provides a longer, more polished version of the meme-heavy adventure. Enjoy a mix of new and classic levels in this definitive N64 party mod.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bowsers-dank-rave-3---toadettes-mlg-expansion', 'N64', 'Bowser''s Dank Rave 3 - Toadette''s MLG Expansion', '2018', 'Meme', 'ROM Hack Community', '1', 'Meme Platformer', 'Surreal platforming with new characters and MLG memes.', 'Help Toadette dominate the rave and find the secrets.', 'The third entry in the series, focusing on Toadette.', 'Bowser''s Dank Rave 3 - Toadette''s MLG Expansion adds new assets and even more specialized internet humor. Experience the Mushroom Kingdom''s wildest party yet on the N64.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bowsers-dank-rave-3-chaos-edition', 'N64', 'Bowser''s Dank Rave 3 (Chaos Edition)', '2018', 'Meme', 'ROM Hack Community', '1', 'Meme Platformer', 'High-speed chaotic platforming featuring Toadette.', 'Conquer the MLG expansion in high-speed chaos mode.', 'The chaotic version of the third Dank Rave title.', 'Bowser''s Dank Rave 3 (Chaos Edition) brings the madness to a whole new level. Fast-paced music and unpredictable hazards make this a legendary N64 community challenge.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bowsers-dank-rave-4---marios-dank-disco', 'N64', 'Bowser''s Dank Rave 4 - Mario''s Dank Disco', '2018', 'Platformer', 'Kaze Emanuar', '1', 'ROM Hack / Meme', 'Surreal platforming with a disco-themed makeover.', 'Dance through the levels and collect the stars as Mario.', 'The fourth installment of the long-running meme saga.', 'Bowser''s Dank Rave 4 - Mario''s Dank Disco blends classic platforming with high-energy visuals. It’s a rhythmic and humorous journey through a neon-colored N64 world.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bowsers-dank-rave-4-chaos-edition', 'N64', 'Bowser''s Dank Rave 4 (Chaos Edition)', '2018', 'Platformer', 'Kaze Emanuar', '1', 'ROM Hack / Meme', 'High-speed chaotic platforming with disco aesthetics.', 'Master the dance floor with accelerated chaos physics.', 'The "Chaos Edition" of the fourth Dank Disco installment.', 'Bowser''s Dank Rave 4 (Chaos Edition) turns the disco into a whirlwind of activity. Navigate through flashing lights and fast obstacles in this unique fan modification.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bowsers-dank-rave-5---reused-levels-edition', 'N64', 'Bowser''s Dank Rave 5 - Reused Levels Edition', '2019', 'Platformer', 'Kaze Emanuar', '1', 'ROM Hack / Meme', 'Surreal platforming with remixed and classic levels.', 'Re-experience the best of the rave in a new package.', 'The fifth entry, featuring a "best-of" level selection.', 'Bowser''s Dank Rave 5 brings back favorite moments with new twists. It’s a nostalgic and funny trip through the history of this N64 modding series.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bowsers-dank-rave-5-chaos-edition', 'N64', 'Bowser''s Dank Rave 5 (Chaos Edition)', '2019', 'Platformer', 'Kaze Emanuar', '1', 'ROM Hack / Meme', 'High-speed chaotic platforming with reused level assets.', 'survive the remixed levels with maximum chaos active.', 'The chaotic revision of the fifth Dank Rave game.', 'Bowser''s Dank Rave 5 (Chaos Edition) adds speed and unpredictability to familiar stages. Re-learn the paths in this frantic and humorous N64 adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bowsers-dank-rave-65-skelenio-edition', 'N64', 'Bowser''s Dank Rave 65 Skelenio Edition', '2020', 'Platformer', 'Kaze Emanuar', '1', 'ROM Hack / Meme', 'Surreal platforming with a skeletal and bone theme.', 'Survive the rave as Skelenio in this spooky expansion.', 'The 65th (humorously numbered) entry in the rave series.', 'Bowser''s Dank Rave 65 Skelenio Edition features a unique spooky aesthetic. Navigate through bone-filled raves in this creative and funny addition to the N64 mod library.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bowsers-dank-rave-65-skelenio-edition-chaos-edition', 'N64', 'Bowser''s Dank Rave 65 Skelenio Edition (Chaos Edition)', '2020', 'Platformer', 'Kaze Emanuar', '1', 'ROM Hack / Meme', 'High-speed skeletal platforming with maximum chaos.', 'Complete the Skelenio rave with extreme speed settings.', 'The chaotic version of the Skelenio-themed rave.', 'Bowser''s Dank Rave 65 Skelenio Edition (Chaos Edition) is as wild as the name suggests. Experience high-speed, bone-chilling disco action on your Nintendo 64.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('boyfriend-64', 'N64', 'Boyfriend 64', '2021', 'Platformer', 'Independent', '1', 'ROM Hack', 'Rhythm-based platforming with a Boyfriend character model.', 'Use your musical skills to navigate the custom levels.', 'A character mod inspired by Friday Night Funkin''.', 'Boyfriend 64 brings the rhythm-game hero to the N64. Experience classic platforming with a custom model and musical flair in this fun community project.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('brunswick-circuit-pro-bowling-usa', 'N64', 'Brunswick Circuit Pro Bowling (USA)', '1998', 'Sports / Bowling', 'Frontline Studios', '4', 'Arcade Sports', 'Professional bowling simulation with licensed tournaments.', 'Win the world tour and master the art of the perfect strike.', 'A detailed and realistic bowling title for the N64.', 'Brunswick Circuit Pro Bowling (USA) features authentic physics and licensed pros. With deep customization and a variety of lanes, it’s the premier bowling experience for the system.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('buck-bumble-europe-enfrdeesit', 'N64', 'Buck Bumble (Europe) (En,Fr,De,Es,It)', '1998', 'Action / Platformer', 'Argonaut Games', '1', '3D Platformer', 'Action-shooter with flight-based combat and a bug theme.', 'Lead Buck the Bee to defend the hive from an alien invasion.', 'The European version of the iconic rhythmic shooter.', 'Buck Bumble (Europe) features a legendary soundtrack and intense aerial combat. Use specialized insect weaponry to save the garden in this stylish N64 title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('buck-bumble-japan', 'N64', 'Buck Bumble (Japan)', '1998', 'Action / Platformer', 'Argonaut Games', '1', '3D Platformer', 'Action-shooter with flight-based combat and a bug theme.', 'Master the aerial combat in this Japanese localized release.', 'The Japanese version of the cult classic Buck Bumble.', 'Buck Bumble (Japan) brings the high-flying bee action to Japan. Enjoy the unique mix of 3D exploration and rhythmic combat that made this game a fan favorite.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('buck-bumble-usa', 'N64', 'Buck Bumble (USA)', '1998', 'Action / Platformer', 'Argonaut Games', '1', '3D Platformer', 'Action-shooter with flight-based combat and a bug theme.', 'Defeat the cyborg insects and protect the Queen.', 'The North American release of the iconic shooter.', 'Buck Bumble (USA) is a technical and musical marvel. Pilot Buck through 20 diverse missions and enjoy the famous title track in this high-energy N64 adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bugs-life-a-europe', 'N64', 'Bug''s Life, A (Europe)', '1998', 'Action / Platformer', 'Traveller''s Tales', '1', '3D Platformer', '3D action-platforming based on the Pixar film.', 'Lead Flik to save the ant colony from the grasshoppers.', 'The European multi-language release of the Disney classic.', 'Bug''s Life, A (Europe) features vibrant levels and puzzles. Explore the world from an ant''s perspective and use specialized seeds to navigate the environment.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bugs-life-a-france', 'N64', 'Bug''s Life, A (France)', '1998', 'Action / Platformer', 'Traveller''s Tales', '1', '3D Platformer', '3D action-platforming with localized French text.', 'Complete the missions in the meadow as the ant hero Flik.', 'The localized French version of the Pixar platformer.', 'Bug''s Life, A (France) offers the full animated adventure for French fans. Master the platforming challenges and defeat the grasshopper gang on the N64.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bugs-life-a-germany', 'N64', 'Bug''s Life, A (Germany)', '1998', 'Action / Platformer', 'Traveller''s Tales', '1', '3D Platformer', '3D action-platforming with localized German text.', 'Protect the colony and gather the harvest in Germany.', 'The localized German version of the Bug''s Life title.', 'Bug''s Life, A (Germany) brings the magic of the film to German players. Experience the diverse 3D worlds and clever gadget-based gameplay on your console.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bugs-life-a-italy', 'N64', 'Bug''s Life, A (Italy)', '1998', 'Action / Platformer', 'Traveller''s Tales', '1', '3D Platformer', '3D action-platforming with localized Italian text.', 'Explore the human world and find the circus bugs.', 'The localized Italian version of the movie-based platformer.', 'Bug''s Life, A (Italy) features the same charming story and varied gameplay for the Italian market. Help Flik prove his worth as a hero in this N64 classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bugs-life-a-usa', 'N64', 'Bug''s Life, A (USA)', '1998', 'Action / Platformer', 'Traveller''s Tales', '1', '3D Platformer', '3D action-platforming with cinematic clips and puzzles.', 'Defeat Hopper and find the warrior bugs in North America.', 'The definitive North American release of the Disney hit.', 'Bug''s Life, A (USA) is a faithful recreation of the movie''s charm. With massive levels and fun power-ups, it''s a nostalgic platforming experience for all ages on the N64.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bullet-bill-simulator', 'N64', 'Bullet Bill Simulator', '2022', 'Simulation / Platformer', 'Independent', '1', 'ROM Hack', 'Action simulation featuring a projectile Bullet Bill.', 'Pilot a Bullet Bill through obstacle courses without crashing.', 'A creative technical mod for the Super Mario 64 engine.', 'Bullet Bill Simulator is a test of precision flying. Navigate through narrow gaps and around moving targets in this unique and challenging N64 fan project.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bust-a-move-99-usa', 'N64', 'Bust-A-Move ''99 (USA)', '1999', 'Puzzle', 'Taito', '2', 'Arcade Puzzle', 'Bubble-matching puzzle action with competitive modes.', 'Clear the screen by matching colored bubbles and win.', 'A modern N64 update of the classic puzzle franchise.', 'Bust-A-Move ''99 (USA) features a variety of characters and a deep puzzle mode. Experience the addictive gameplay of the series with polished 64-bit graphics.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bust-a-move-2---arcade-edition-europe', 'N64', 'Bust-A-Move 2 - Arcade Edition (Europe)', '1999', 'Puzzle', 'Taito', '2', 'Arcade Puzzle', 'Bubble-matching puzzle action with an arcade-style spirit.', 'Defeat the computer or friends in high-speed matches.', 'The European release of the classic arcade puzzler.', 'Bust-A-Move 2 - Arcade Edition (Europe) is a test of reflexes and strategy. Master the angles and clear the board in this timeless N64 puzzle game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bust-a-move-2---arcade-edition-usa', 'N64', 'Bust-A-Move 2 - Arcade Edition (USA)', '1999', 'Puzzle', 'Taito', '2', 'Arcade Puzzle', 'Bubble-matching puzzle action with an arcade-style spirit.', 'Reach the highest level in the endless puzzle mode.', 'The North American release of the arcade puzzle hit.', 'Bust-A-Move 2 - Arcade Edition (USA) features the iconic Taito characters and addictive gameplay. It remains one of the best local multiplayer games on the system.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bust-a-move-3-dx-europe', 'N64', 'Bust-A-Move 3 DX (Europe)', '1998', 'Puzzle', 'Taito', '2', 'Arcade Puzzle', 'Bubble-matching puzzle action with expanded content.', 'Solve hundreds of new puzzles in the deluxe edition.', 'The European version of the third Bust-A-Move game.', 'Bust-A-Move 3 DX (Europe) adds new bubble types and mechanics. With a massive puzzle library and improved visuals, it’s a deep and rewarding experience for puzzle fans.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('california-speed-usa', 'N64', 'California Speed (USA)', '1999', 'Racing', 'Midway Games', '2', 'Arcade Racing', 'High-speed arcade racing with futuristic and classic cars.', 'Race across California landmarks and finish in first place.', 'A fast-paced, over-the-top arcade racer for the N64.', 'California Speed (USA) brings the thrill of the arcade home. Drive through malls, UFOs, and Mt. Shasta at breakneck speeds in this high-energy racing classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('carmageddon-64-europe-enfrdees', 'N64', 'Carmageddon 64 (Europe) (En,Fr,De,Es)', '1999', 'Action / Racing', 'Stainless Games', '1', 'Vehicular Combat', 'Vehicular combat and racing with destructible environments.', 'Win the race or destroy all opponents and pedestrians.', 'The European version of the controversial combat racer.', 'Carmageddon 64 (Europe) features brutal car-to-car combat and open-world freedom. Survive the chaos and wreck your way to victory in this gritty N64 title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('carmageddon-64-europe-enfresit', 'N64', 'Carmageddon 64 (Europe) (En,Fr,Es,It)', '1999', 'Action / Racing', 'Stainless Games', '1', 'Vehicular Combat', 'Vehicular combat and racing with localized languages.', 'Eliminate the competition in this intense multi-language build.', 'An alternative European release of the car-combat title.', 'Carmageddon 64 (Europe) (En,Fr,Es,It) provides the same destructive gameplay with localized text for the Mediterranean market. High-octane carnage on the N64.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('carmageddon-64-usa', 'N64', 'Carmageddon 64 (USA)', '1999', 'Action / Racing', 'Stainless Games', '1', 'Vehicular Combat', 'Vehicular combat and racing with high-impact crashes.', 'Reach the checkpoints or total every other car on the track.', 'The North American release of the infamous combat racer.', 'Carmageddon 64 (USA) is known for its open-ended mission structure and physics-based destruction. Choose your vehicle and unleash mayhem in this 64-bit cult classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('cascade-slide', 'N64', 'Cascade Slide', '2020', 'Platformer', 'Independent', '1', 'ROM Hack', 'High-speed sliding with water and physics obstacles.', 'Master the steep curves and reach the bottom safely.', 'A technical sliding mod featuring cascading water effects.', 'Cascade Slide is a test of precision and momentum. Navigate through fluid-filled paths and sharp drops in this refreshing and difficult N64 fan project.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('casino-bingo-slide', 'N64', 'Casino Bingo Slide', '2020', 'Platformer', 'Independent', '1', 'ROM Hack', 'Casino-themed sliding challenge with randomized hazards.', 'Win big by reaching the end of the slide with a high score.', 'A creative mod blending gambling aesthetics with sliding.', 'Casino Bingo Slide features a unique neon look and arcade mechanics. Collect coins and hit the jackpot while sliding through this vibrant N64 level.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('castle-grounds-revamp', 'N64', 'Castle Grounds Revamp', '2021', 'Platformer', 'Independent', '1', 'ROM Hack', '3D platforming in a modernized castle environment.', 'Explore a visually enhanced version of Peach''s Castle.', 'A high-quality visual overhaul of the classic hub world.', 'Castle Grounds Revamp upgrades the iconic Mario 64 exterior with new models and high-res textures. Experience the familiar grounds with modern modding polish.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('castle-ungrounded', 'N64', 'Castle Ungrounded', '2021', 'Platformer', 'Independent', '1', 'ROM Hack', '3D platforming in a distorted, floating castle world.', 'Navigate through a gravity-defying version of the castle hub.', 'A surreal mod that reimagines the castle without a floor.', 'Castle Ungrounded challenges your perception of space. Explore the floating rooms and exterior of the castle in this creative and vertigo-inducing N64 project.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('castlevania---legacy-of-darkness-europe-enfrde', 'N64', 'Castlevania - Legacy of Darkness (Europe) (En,Fr,De)', '1999', 'Action / Adventure', 'Konami', '1', '3D Action', 'Gothic action-adventure with multiple playable characters.', 'Defeat Dracula''s forces as Cornell, Henry, or Reinhardt.', 'The definitive European release of the expanded 3D Castlevania.', 'Castlevania - Legacy of Darkness (Europe) is the ultimate 3D hunt. Master the man-beast Cornell''s powers in this atmospheric and content-rich gothic adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('castlevania---legacy-of-darkness-usa', 'N64', 'Castlevania - Legacy of Darkness (USA)', '1999', 'Action / Adventure', 'Konami', '1', '3D Action', 'Gothic action-adventure with multiple playable characters.', 'Stop the resurrection of the Dark Lord in the definitive version.', 'The expanded North American release of the 3D Castlevania.', 'Castlevania - Legacy of Darkness (USA) features improved lighting, new bosses, and multiple storylines. It is the most complete Castlevania experience on the system.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('castlevania-europe-enfrde', 'N64', 'Castlevania (Europe) (En,Fr,De)', '1999', 'Action / Adventure', 'Konami', '1', '3D Action', '3D action-adventure with a dark, cinematic atmosphere.', 'Navigate the Castle as Carrie or Reinhardt to find Dracula.', 'The first European entry of the series into the 3D realm.', 'Castlevania (Europe) captures the moody essence of the franchise. Battle the undead with whips and magic in this landmark 64-bit horror-adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('castlevania-usa', 'N64', 'Castlevania (USA)', '1999', 'Action / Adventure', 'Konami', '1', '3D Action', '3D action-adventure with a dark, cinematic atmosphere.', 'Survive the clock tower and the forest of silence.', 'The original North American release of Castlevania 64.', 'Castlevania (USA) brings the Belmont legacy to life with challenging platforming and intense boss fights. Experience the dawn of 3D gothic horror on the N64.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('castlevania-usa-rev-a', 'N64', 'Castlevania (USA) (Rev A)', '1999', 'Action / Adventure', 'Konami', '1', '3D Action', '3D action-adventure with technical fixes and polish.', 'Experience the dark hunt with improved game stability.', 'An updated North American revision of Castlevania 64.', 'Castlevania (USA) (Rev A) provides minor bug fixes and performance tweaks, ensuring a smoother journey through Dracula''s castle for N64 players.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('castlevania-usa-rev-b', 'N64', 'Castlevania (USA) (Rev B)', '1999', 'Action / Adventure', 'Konami', '1', '3D Action', '3D action-adventure with final logic and asset corrections.', 'Conquer the castle with the most stable US build.', 'The final technical revision of the original 3D Castlevania.', 'Castlevania (USA) (Rev B) is the most refined version of the base game, offering optimized performance and corrected event triggers for N64 fans.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ceaseless-climb', 'N64', 'Ceaseless Climb', '2021', 'Platformer', 'Independent', '1', 'ROM Hack', 'Vertical 3D platforming challenge with infinite elements.', 'Climb as high as possible without falling into the void.', 'A grueling endurance mod for the Super Mario 64 engine.', 'Ceaseless Climb is a test of stamina and skill. Master the wall kick and triple jump to reach impossible heights in this challenging and minimal N64 fan project.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('centre-court-tennis-europe', 'N64', 'Centre Court Tennis (Europe)', '1998', 'Sports / Tennis', 'Eurocom', '4', 'Simulation', 'Realistic tennis simulation with professional mechanics.', 'Win the tournament and master the grass and clay courts.', 'A technical tennis title released for the European market.', 'Centre Court Tennis (Europe) features smooth animations and deep strategy. Compete in singles or doubles matches with intuitive N64 controls.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('chambers-of-nonsense', 'N64', 'Chambers of Nonsense', '2020', 'Platformer', 'Independent', '1', 'ROM Hack', 'Surreal 3D platforming in an abstract world of chaos.', 'Navigate through rooms filled with nonsensical geometry.', 'A humorous and bizarre mod focused on "weird" physics.', 'Chambers of Nonsense is a trip through the strange. Solve weird puzzles and navigate glitchy environments in this creative and funny N64 community project.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('chameleon-twist-europe', 'N64', 'Chameleon Twist (Europe)', '1997', 'Action / Platformer', 'Sunsoft', '1', '3D Platformer', '3D platformer featuring a chameleon with a grapple tongue.', 'Use your tongue to swing, eat, and defeat bosses.', 'The charming European release of the unique 3D platformer.', 'Chameleon Twist (Europe) features innovative tongue-based physics. Swing across gaps and rotate around poles in this colorful and creative N64 adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('chameleon-twist-japan', 'N64', 'Chameleon Twist (Japan)', '1997', 'Action / Platformer', 'Sunsoft', '1', '3D Platformer', '3D platformer featuring a chameleon with a grapple tongue.', 'Rescue your friends in the magical Japanese world.', 'The original Japanese release of the lizard-based platformer.', 'Chameleon Twist (Japan) introduced the world to its unique grappling mechanics. Explore diverse worlds from the Land of Sweets to the Ghost Castle.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('chameleon-twist-usa', 'N64', 'Chameleon Twist (USA)', '1997', 'Action / Platformer', 'Sunsoft', '1', '3D Platformer', '3D platformer featuring a chameleon with a grapple tongue.', 'Master the tongue-swinging mechanics to find every secret.', 'The North American release of the cult classic platformer.', 'Chameleon Twist (USA) is known for its quirky charm and unique control scheme. Use your lizard''s tongue as a multi-tool in this imaginative 64-bit title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('chameleon-twist-usa-rev-a', 'N64', 'Chameleon Twist (USA) (Rev A)', '1997', 'Action / Platformer', 'Sunsoft', '1', '3D Platformer', '3D platformer with refined physics and minor fixes.', 'Swing through the levels with improved game stability.', 'An updated revision of the North American Chameleon Twist.', 'Chameleon Twist (USA) (Rev A) provides a more polished experience of the grappling action, ensuring smooth performance on your Nintendo 64.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('chameleon-twist-2-europe', 'N64', 'Chameleon Twist 2 (Europe)', '1998', 'Action / Platformer', 'Sunsoft', '1', '3D Platformer', '3D platformer with verticality and improved mechanics.', 'Use the enhanced tongue moves to navigate complex worlds.', 'The European release of the stylish lizard-based sequel.', 'Chameleon Twist 2 (Europe) features a more refined art style and deeper platforming. Master the new parachute and pogo moves in this creative N64 sequel.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('chameleon-twist-2-japan', 'N64', 'Chameleon Twist 2 (Japan)', '1998', 'Action / Platformer', 'Sunsoft', '1', '3D Platformer', '3D platformer with verticality and improved mechanics.', 'Master the new transformations in the Japanese edition.', 'The original Japanese release of the Chameleon Twist sequel.', 'Chameleon Twist 2 (Japan) expands on the grappling concept with even more creative level design and colorful, 64-bit environments.');